fn frame(t: i32) {
    host::display::clear(0x000000);
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let mut m: i32 = w;
    if h < m { m = h; }
    let r: i32 = m / 3 + (8 * host::math::sin(t)) / 256;
    let mut a: i32 = 0;
    while a < 256 {
        let x0: i32 = cx + (r * host::math::cos(a)) / 256;
        let y0: i32 = cy + (r * host::math::sin(a)) / 256;
        let x1: i32 = cx + (r * host::math::cos(a + 4)) / 256;
        let y1: i32 = cy + (r * host::math::sin(a + 4)) / 256;
        host::display::draw_line(x0, y0, x1, y1, 0xffffff);
        a = a + 4;
    }
    host::display::fill_rect(cx - 2, cy - 2, 4, 4, 0xffffff);
    host::display::present();
}
